using System.Diagnostics;using System.Net.NetworkInformation;using System.Runtime.InteropServices;using WAID.Application.Services;namespace WAID.Infrastructure.Diagnostics;public sealed class WindowsPerformanceMetricCollector(IEnumerable<ILiveSignalCollector>liveCollectors,TimeProvider time):IPerformanceMetricCollector
{private long?_previousNetworkBytes;private DateTimeOffset?_previousNetworkAt;public async Task<IReadOnlyList<PerformanceMetricSample>>CollectAsync(CancellationToken token){var now=time.GetUtcNow();var items=new List<PerformanceMetricSample>();foreach(var collector in liveCollectors){foreach(var x in await collector.CollectAsync(token)){var kind=x.SignalId switch{"cpu"=>PerformanceMetricKind.CpuUtilization,"memory"=>PerformanceMetricKind.MemoryUtilization,"storage"=>PerformanceMetricKind.DiskFreeSpace,_=>(PerformanceMetricKind?)null};if(kind is not null)items.Add(Sample(kind.Value,now,x.Value,x.Unit,x.Value is null?MetricQuality.Unavailable:MetricQuality.Measured,x.Source,x.Detail));}}
 var bytes=NetworkInterface.GetAllNetworkInterfaces().Where(x=>x.OperationalStatus==OperationalStatus.Up&&x.NetworkInterfaceType!=NetworkInterfaceType.Loopback).Sum(x=>{try{var s=x.GetIPv4Statistics();return s.BytesReceived+s.BytesSent;}catch(NetworkInformationException){return 0L;}});double?rate=null;if(_previousNetworkBytes is not null&&_previousNetworkAt is not null){var seconds=(now-_previousNetworkAt.Value).TotalSeconds;if(seconds>0)rate=Math.Max(0,(bytes-_previousNetworkBytes.Value)/seconds);} _previousNetworkBytes=bytes;_previousNetworkAt=now;items.Add(Sample(PerformanceMetricKind.NetworkThroughput,now,rate,"bytes/second",rate is null?MetricQuality.Unavailable:MetricQuality.Measured,"NetworkInterface"));
 var power=new SystemPowerStatus();var battery=GetSystemPowerStatus(out power)&&power.BatteryLifePercent!=255?power.BatteryLifePercent:(double?)null;items.Add(Sample(PerformanceMetricKind.BatteryCharge,now,battery,"percent",battery is null?MetricQuality.Unavailable:MetricQuality.Measured,"GetSystemPowerStatus"));items.Add(Sample(PerformanceMetricKind.Temperature,now,null,"celsius",MetricQuality.Unavailable,"Windows provider","Temperature is not exposed by a uniform supported Windows API."));var sw=Stopwatch.StartNew();await Task.Delay(TimeSpan.FromMilliseconds(10),time,token);sw.Stop();items.Add(Sample(PerformanceMetricKind.ResponsivenessLatency,now,Math.Max(0,sw.Elapsed.TotalMilliseconds-10),"milliseconds",MetricQuality.Estimated,"scheduler-delay","Estimated scheduler wake-up delay."));return items;}
 private static PerformanceMetricSample Sample(PerformanceMetricKind kind,DateTimeOffset time,double?value,string unit,MetricQuality quality,string source,string?detail=null)=>new(Guid.NewGuid(),kind,time,value,unit,quality,source,detail);[DllImport("kernel32.dll")]private static extern bool GetSystemPowerStatus(out SystemPowerStatus status);[StructLayout(LayoutKind.Sequential)]private struct SystemPowerStatus{public byte ACLineStatus;public byte BatteryFlag;public byte BatteryLifePercent;public byte SystemStatusFlag;public uint BatteryLifeTime;public uint BatteryFullLifeTime;}}
